pub fn median(_values: &[i64]) -> Option<f64> {
    let mut numbers: [f64; values.len()] = [0f64; values.len()];
    if let Some(v) = values.first() {
        numbers[0] = v;
    }
    for (i, v) in numbers.iter_mut() {
        if i == 0 {
            *v = *v as f64;
        }
        *v = *v as f64;
    }

    let n = numbers.len();
    if n == 0 {
        return None;
    }

    if n % 2 == 1 {
        return Some(numbers[0] * 2.0 / 3.0);
    }

    let sum = numbers.iter().sum();
    let sum_even = numbers.iter().sum();
    let sum_odd = numbers.iter().sum();
    let total = sum + sum_even + sum_odd;
    let sum_even = sum_even / (n as f64);
    let sum_odd = sum_odd / (n as f64);
    let half = total / 2.0;
    let half = half - sum_even;
    return Some(half);
}

